 pitfalls:['Excluir lesão de aorta só porque a radiografia está normal.','Hidratar agressivamente a contusão pulmonar.','Não fazer ECG no trauma torácico fechado.'],
 recall:[
  {q:'Local mais comum da ruptura traumática da aorta?',a:'Istmo aórtico, junto ao ligamento arterioso, distal à subclávia esquerda.'},
  {q:'Cite quatro sinais radiológicos de lesão de aorta.',a:'Mediastino alargado, apagamento do botão aórtico, desvio da traqueia ou SNG para a direita, rebaixamento do brônquio fonte esquerdo.'},
  {q:'Tratamento preferido da lesão de aorta que exige reparo e tem anatomia favorável?',a:'Reparo endovascular (TEVAR), com estratégia de controle hemodinâmico individualizada; a indicação depende da morfologia e das lesões associadas.'},
  {q:'Como evolui a contusão pulmonar?',a:'Piora em 24 a 48 horas; tratamento de suporte e cuidado com volume.'},
  {q:'Sinal de lesão traqueobrônquica após drenagem?',a:'Fuga aérea persistente e pulmão que não expande.'},
  {q:'Toda lesão traumática de aorta deve receber TEVAR imediatamente?',a:'Não. Morfologia, extensão, estabilidade, lesões associadas e avaliação vascular definem a necessidade e o momento do reparo ou de vigilância.'},
  {q:'Qual a função do ecocardiograma no trauma cardíaco contuso com instabilidade?',a:'Investigar repercussões funcionais e estruturais que possam explicar o choque ou uma arritmia relevante, após considerar outras causas.'},
  {q:'Por que pneumomediastino não é sinônimo de ruptura de esôfago?',a:'Porque ar pode vir da via aérea, do pulmão ou do esôfago; mecanismo, trajeto e avaliação dirigida discriminam as causas.'}],
 practice:['Liste de memória seis sinais radiológicos de lesão de aorta.'],
 cases:[{title:'Suspeita vascular com radiografia pouco expressiva',data:['Adulto sofreu desaceleração importante e mantém condições para investigação.','A radiografia não mostra alteração mediastinal convincente, mas o mecanismo e os achados associados mantêm suspeita vascular.'],reasoning:['Radiografia normal não exclui lesão aórtica.','A anatomia precisa ser caracterizada antes de assumir que basta observar ou que todos receberão o mesmo reparo.'],conduct:['Realizar angioTC conforme indicação e segurança clínica.','Definir estratégia com a equipe vascular segundo morfologia e lesões associadas, mantendo a perfusão durante o cuidado.'],error:'Encerrar a investigação pela ausência de mediastino largo na radiografia.'},{title:'Hipoxemia que piora após trauma fechado',data:['Paciente com dor por fraturas costais e opacidades compatíveis com contusão.','Na evolução, aumenta o trabalho respiratório.'],reasoning:['A contusão pode evoluir, mas a piora também exige buscar atelectasia, pneumotórax e problemas da via aérea ou do suporte.','Analgesia inadequada e secreções retidas reduzem a ventilação efetiva.'],conduct:['Repetir avaliação torácica e ajustar analgesia, suporte e higiene pulmonar.','Oferecer ventilação quando necessária e adequar reposição ao balanço entre perfusão e risco de edema.'],error:'Atribuir toda deterioração à contusão conhecida e deixar de procurar uma causa tratável associada.'}],
